public class Codec {
    public string serialize(TreeNode root) {
        var sb = new StringBuilder();
        Write(root, sb);
        return sb.ToString();
    }

    private static void Write(TreeNode node, StringBuilder sb) {
        if (sb.Length > 0) sb.Append(',');
        if (node == null) { sb.Append('#'); return; }   // маркер: здесь ветка кончается
        sb.Append(node.val);                            // pre-order: узел раньше детей
        Write(node.left, sb);
        Write(node.right, sb);
    }

    public TreeNode deserialize(string data) {
        int pos = 0;
        return Read(data.Split(','), ref pos);
    }

    private static TreeNode Read(string[] tokens, ref int pos) {
        string t = tokens[pos++];                       // курсор идёт только вперёд
        if (t == "#") return null;
        var node = new TreeNode(int.Parse(t));
        node.left = Read(tokens, ref pos);              // тот же порядок, что в Write
        node.right = Read(tokens, ref pos);
        return node;
    }
}

